import { readFile } from "node:fs/promises";
import path from "node:path";

const NAMES = ["AGENTS.md", "HARNESS.md"];

export async function loadContext(cwd: string) {
  const chunks: string[] = [];
  for (const name of NAMES) {
    try {
      const body = (await readFile(path.join(cwd, name), "utf8")).trim();
      if (body) chunks.push(`## ${name}\n${body}`);
    } catch {
      // file is optional
    }
  }
  return chunks.join("\n\n");
}

src/delivery.ts.body:
import { createHash } from "node:crypto";
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { APP_VERSION } from "./brand.ts";
import { packageRoot } from "./env.ts";
import { harnessRoot } from "./session.ts";

export type CriterionStatus = "passed" | "failed" | "blocked" | "not_run";

export type Criterion = {
  id: string;
  text: string;
};

export type Agreement = {
  id: string;
  objective: string;
  scope: string[];
  acceptance: Criterion[];
  exclusions: string[];
  references?: string[];
  status: "proposed" | "confirmed";
  confirmedAt?: string;
  confirmedBy?: "owner";
};

export type Revision = {
  at: string;
  reason: string;
  weakened: boolean;
  before: { acceptance: string[]; exclusions: string[] };
  after: { acceptance: string[]; exclusions: string[] };
};

export type SourceIdentity = {
  version: string;
  git: string;
  srcHash: string;
  node: string;
  platform: string;
  at: string;
};

export type CheckRecord = {
  criterionId: string;
  status: CriterionStatus;
  stale?: boolean;
  command: string;
  exitCode?: number;
  output: string;
  kind: "command" | "test" | "file";
  identity: SourceIdentity;
  at: string;
};

export type TaskRecord = {
  agreement: Agreement;
  revisions: Revision[];
  checks: CheckRecord[];
  changed: string[];
  screenshots: { path: string; caption: string }[];
  implemented: boolean;
  ownerAccepted: boolean;
  ownerAcceptedAt?: string;
};

const DISCLAIMERS = [
  "Screenshots do not prove functionality.",
  "Tests passing is not product acceptance.",
  "Jev scores are not OS isolation or spending limits.",
];

export function taskDir(cwd: string) {
  return path.join(harnessRoot(cwd), "task");
}

function taskFile(cwd: string, name: string) {
  return path.join(taskDir(cwd), name);
}

export async function captureIdentity(): Promise<SourceIdentity> {
  const root = packageRoot();
  let git = "unknown";
  try {
    const head = (await readFile(path.join(root, ".git", "HEAD"), "utf8")).trim();
    if (head.startsWith("ref: ")) {
      git = (await readFile(path.join(root, ".git", head.slice(5).trim()), "utf8")).trim();
    } else {
      git = head;
    }
  } catch {
    git = "unknown";
  }
  const hash = createHash("sha256");
  await hashDir(path.join(root, "src"), hash, root);
  hash.update(APP_VERSION);
  return {
    version: APP_VERSION,
    git,
    srcHash: hash.digest("hex").slice(0, 16),
    node: process.version,
    platform: `${os.platform()} ${os.release()}`,
    at: new Date().toISOString(),
  };
}

async function hashDir(dir: string, hash: ReturnType<typeof createHash>, root: string) {
  let entries: import("node:fs").Dirent[] = [];
  try {
    entries = (await readdir(dir, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name));
  } catch {
    return;
  }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      await hashDir(full, hash, root);
      continue;
    }
    if (!entry.name.endsWith(".ts")) continue;
    hash.update(path.relative(root, full));
    hash.update(await readFile(full, "utf8"));
  }
}

async function writeJson(file: string, value: unknown) {
  await mkdir(path.dirname(file), { recursive: true });
  await writeFile(file, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

async function readJson<T>(file: string): Promise<T | undefined> {
  try {
    return JSON.parse(await readFile(file, "utf8")) as T;
  } catch {
    return undefined;
  }
}

export async function loadTask(cwd: string): Promise<TaskRecord | undefined> {
  const agreement = await readJson<Agreement>(taskFile(cwd, "agreement.json"));
  if (!agreement) return undefined;
  const revisions = (await readJson<Revision[]>(taskFile(cwd, "revisions.json"))) ?? [];
  const checks = (await readJson<CheckRecord[]>(taskFile(cwd, "evidence.json"))) ?? [];
  const meta =
    (await readJson<{
      changed?: string[];
      screenshots?: { path: string; caption: string }[];
      implemented?: boolean;
      ownerAccepted?: boolean;
      ownerAcceptedAt?: string;
    }>(taskFile(cwd, "meta.json"))) ?? {};
  const identity = await captureIdentity();
  const checksWithStale = checks.map((check) => {
    if (check.status !== "passed") return check;
    if (check.identity.srcHash !== identity.srcHash) return { ...check, stale: true };
    return { ...check, stale: false };
  });
  return {
    agreement,
    revisions,
    checks: checksWithStale,
    changed: meta.changed ?? [],
    screenshots: meta.screenshots ?? [],
    implemented: meta.implemented === true,
    ownerAccepted: meta.ownerAccepted === true,
    ownerAcceptedAt: meta.ownerAcceptedAt,
  };
}

export async function writeAgreement(cwd: string, agreement: Agreement) {
  if (agreement.status === "confirmed") {
    throw new Error("Use confirmAgreement. Do not write a confirmed agreement directly.");
  }
  const proposed = { ...agreement, status: "proposed" as const };
  delete proposed.confirmedAt;
  delete proposed.confirmedBy;
  await writeJson(taskFile(cwd, "agreement.json"), proposed);
  await writeJson(taskFile(cwd, "revisions.json"), []);
  await writeJson(taskFile(cwd, "evidence.json"), []);
  await writeJson(taskFile(cwd, "meta.json"), {
    changed: [],
    screenshots: [],
    implemented: false,
    ownerAccepted: false,
  });
  return proposed;
}

export async function confirmAgreement(cwd: string, actor: "owner") {
  if (actor !== "owner") throw new Error("Only the owner can confirm the agreement.");
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  const confirmed: Agreement = {
    ...task.agreement,
    status: "confirmed",
    confirmedAt: new Date().toISOString(),
    confirmedBy: "owner",
  };
  await writeJson(taskFile(cwd, "agreement.json"), confirmed);
  return confirmed;
}

export function assertReadyToImplement(task: TaskRecord) {
  if (task.agreement.status !== "confirmed") {
    throw new Error("Owner has not confirmed the agreement.");
  }
}

function ids(list: Criterion[]) {
  return list.map((item) => item.id);
}

export async function reviseAgreement(
  cwd: string,
  next: Pick<Agreement, "objective" | "scope" | "acceptance" | "exclusions" | "references">,
  input: { reason: string; allowWeaken?: boolean },
) {
  if (!input.reason.trim()) throw new Error("Revisions need a reason.");
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  const beforeIds = ids(task.agreement.acceptance);
  const afterIds = ids(next.acceptance);
  const removed = beforeIds.filter((id) => !afterIds.includes(id));
  const droppedExclusion = task.agreement.exclusions.filter((item) => !next.exclusions.includes(item));
  const weakened = removed.length > 0 || droppedExclusion.length > 0;
  if (weakened && !input.allowWeaken) {
    throw new Error("Refusing silent weaken. Pass allowWeaken after the owner agrees.");
  }
  const revision: Revision = {
    at: new Date().toISOString(),
    reason: input.reason,
    weakened,
    before: { acceptance: beforeIds, exclusions: task.agreement.exclusions },
    after: { acceptance: afterIds, exclusions: next.exclusions },
  };
  const agreement: Agreement = {
    ...task.agreement,
    ...next,
    status: "proposed",
    confirmedAt: undefined,
    confirmedBy: undefined,
  };
  await writeJson(taskFile(cwd, "agreement.json"), agreement);
  await writeJson(taskFile(cwd, "revisions.json"), [...task.revisions, revision]);
  const meta = {
    changed: task.changed,
    screenshots: task.screenshots,
    implemented: false,
    ownerAccepted: false,
  };
  await writeJson(taskFile(cwd, "meta.json"), meta);
  return revision;
}

export async function recordCheck(
  cwd: string,
  input: {
    criterionId: string;
    status: CriterionStatus;
    command: string;
    output: string;
    kind: "command" | "test" | "file";
    exitCode?: number;
  },
) {
  if ((input.kind as string) === "summary") {
    throw new Error("Model-authored summaries cannot set a check.");
  }
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  if (!task.agreement.acceptance.some((item) => item.id === input.criterionId)) {
    throw new Error(`Unknown criterion ${input.criterionId}`);
  }
  const record: CheckRecord = {
    criterionId: input.criterionId,
    status: input.status,
    command: input.command,
    output: input.output.slice(0, 8000),
    kind: input.kind,
    exitCode: input.exitCode,
    identity: await captureIdentity(),
    at: new Date().toISOString(),
  };
  const previous = (await readJson<CheckRecord[]>(taskFile(cwd, "evidence.json"))) ?? [];
  previous.push(record);
  await writeJson(taskFile(cwd, "evidence.json"), previous);
  return record;
}

export async function noteChanged(cwd: string, files: string[]) {
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  const changed = [...new Set([...task.changed, ...files])];
  await writeJson(taskFile(cwd, "meta.json"), {
    changed,
    screenshots: task.screenshots,
    implemented: task.implemented,
    ownerAccepted: task.ownerAccepted,
    ownerAcceptedAt: task.ownerAcceptedAt,
  });
}

export async function addScreenshot(cwd: string, shot: { path: string; caption: string }) {
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  await writeJson(taskFile(cwd, "meta.json"), {
    changed: task.changed,
    screenshots: [...task.screenshots, shot],
    implemented: task.implemented,
    ownerAccepted: task.ownerAccepted,
    ownerAcceptedAt: task.ownerAcceptedAt,
  });
}

export async function markImplemented(cwd: string) {
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  assertReadyToImplement(task);
  await writeJson(taskFile(cwd, "meta.json"), {
    changed: task.changed,
    screenshots: task.screenshots,
    implemented: true,
    ownerAccepted: false,
    ownerAcceptedAt: undefined,
  });
}

export async function acceptTask(cwd: string, actor: "owner") {
  if (actor !== "owner") throw new Error("Only the owner can record acceptance.");
  const task = await loadTask(cwd);
  if (!task) throw new Error("No task agreement.");
  if (task.agreement.status !== "confirmed") {
    throw new Error("Confirm the agreement before accepting delivery.");
  }
  await writeJson(taskFile(cwd, "meta.json"), {
    changed: task.changed,
    screenshots: task.screenshots,
    implemented: task.implemented,
    ownerAccepted: true,
    ownerAcceptedAt: new Date().toISOString(),
  });
}

function latestChecks(task: TaskRecord) {
  const map = new Map<string, CheckRecord>();
  for (const check of task.checks) map.set(check.criterionId, check);
  return map;
}

export function renderCard(task: TaskRecord) {
  const latest = latestChecks(task);
  const requested = task.agreement.acceptance.map((item) => `- ${item.id}: ${item.text}`);
  const verified: string[] = [];
  const notVerified: string[] = [];
  for (const item of task.agreement.acceptance) {
    const check = latest.get(item.id);
    if (!check) {
      notVerified.push(`- ${item.id}: not run`);
      continue;
    }
    const result = `${check.status}${check.stale ? " (stale)" : ""}  ${check.command}  exit ${check.exitCode ?? "-"}`;
    if (check.status === "passed" && !check.stale) verified.push(`- ${item.id}: ${result}`);
    else notVerified.push(`- ${item.id}: ${result}`);
  }
  const identity = task.checks.at(-1)?.identity;
  const lines = [
    "Aegis delivery card",
    "",
    `Agreement  ${task.agreement.id}  ${task.agreement.status}`,
    `Approved reference  ${task.agreement.status === "confirmed" ? task.agreement.confirmedAt : "(not confirmed)"}`,
    "",
    "Requested",
    `Objective: ${task.agreement.objective}`,
    ...requested,
    "",
    "Changed",
    ...(task.changed.length ? task.changed.map((file) => `- ${file}`) : ["- (none recorded)"]),
    "",
    "Verified",
    ...(verified.length ? verified : ["- (none)"]),
    "",
    "Not verified",
    ...(notVerified.length ? notVerified : ["- (none)"]),
    "",
    "Evidence",
    ...task.agreement.acceptance.map((item) => {
      const check = latest.get(item.id);
      if (!check) return `- ${item.id}: missing check`;
      const output = check.output.trim().split(/\r?\n/).slice(0, 6).join(" / ");
      return `- ${item.id}: ${check.status} · ${check.command} · ${output || "(no output)"}`;
    }),
    "",
    "Screenshots (appearance only)",
    ...(task.screenshots.length
      ? task.screenshots.map((shot) => `- ${shot.path}  ${shot.caption}`)
      : ["- (none)"]),
    "",
    "Flags (kept separate)",
    `implemented     ${task.implemented ? "yes" : "no"}`,
    `checks passed   ${verified.length}/${task.agreement.acceptance.length}`,
    `owner accepted  ${task.ownerAccepted ? `yes ${task.ownerAcceptedAt}` : "no"}`,
    "",
    identity
      ? `Tested  v${identity.version}  git ${identity.git.slice(0, 12)}  src ${identity.srcHash}  ${identity.platform}  node ${identity.node}`
      : "Tested  (no check recorded)",
    "",
    ...DISCLAIMERS,
  ];
  if (task.revisions.length) {
    lines.push("", "Revisions");
    for (const rev of task.revisions) {
      lines.push(`- ${rev.at}  ${rev.weakened ? "weaken" : "revise"}  ${rev.reason}`);
    }
  }
  return lines.join("\n");
}

export async function renderTaskCard(cwd: string) {
  const task = await loadTask(cwd);
  if (!task) return "No task agreement. Ordinary files live under .harness/task/";
  const card = renderCard(task);
  await writeFile(taskFile(cwd, "card.md"), `${card}\n`, "utf8");
  return card;
}

src/env.ts.body:
import { randomUUID } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { lstat, mkdir, realpath, rename, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { loadConfig } from "./config.ts";

export function parseEnvText(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const eq = line.indexOf("=");
    if (eq <= 0) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    out[key] = value;
  }
  return out;
}

function applyEnvFile(file: string) {
  if (!existsSync(file)) return;
  const parsed = parseEnvText(readFileSync(file, "utf8"));
  for (const [key, value] of Object.entries(parsed)) {
    process.env[key] = value;
  }
}

export function packageRoot() {
  return path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
}

export function loadEnv(cwd = process.cwd()) {
  const root = packageRoot();
  applyEnvFile(path.join(root, ".env"));
  applyEnvFile(path.join(root, ".env.local"));
  applyEnvFile(path.join(cwd, ".env"));
  applyEnvFile(path.join(cwd, ".env.local"));
  return loadConfig(cwd);
}

export function hasJevCredentials() {
  return Boolean(
    process.env.TYPESAFE_API_KEY ||
      process.env.TYPESAFE_AI_API_KEY ||
      process.env.AI_GATEWAY_API_KEY,
  );
}

export function jevApiKey() {
  return (
    process.env.TYPESAFE_API_KEY ||
    process.env.TYPESAFE_AI_API_KEY ||
    process.env.AI_GATEWAY_API_KEY ||
    ""
  );
}

export function hasOpenAiKey() {
  return Boolean(process.env.OPENAI_API_KEY);
}

export function hasOpenCodeKey() {
  return Boolean(process.env.OPENCODE_API_KEY);
}

export function lexicalInsideCwd(target: string, cwd: string) {
  const resolved = path.resolve(cwd, target);
  const root = path.resolve(cwd);
  const rel = path.relative(root, resolved);
  if (rel.startsWith("..") || path.isAbsolute(rel)) {
    throw new Error(`Path is outside the working folder: ${target}`);
  }
  return resolved;
}

function assertRelInside(root: string, candidate: string, label: string) {
  const rel = path.relative(root, candidate);
  if (rel.startsWith("..") || path.isAbsolute(rel)) {
    throw new Error(`Path is outside the working folder: ${label}`);
  }
}

async function realpathOrSelf(target: string) {
  try {
    return await realpath(target);
  } catch {
    return path.resolve(target);
  }
}

export async function assertInsideCwd(target: string, cwd: string) {
  const intended = lexicalInsideCwd(target, cwd);
  const root = await realpathOrSelf(path.resolve(cwd));
  try {
    const st = await lstat(intended);
    if (st.isSymbolicLink() || st.isFile() || st.isDirectory()) {
      const real = await realpath(intended);
      assertRelInside(root, real, target);
      return real;
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }

  const rest: string[] = [];
  let dir = path.dirname(intended);
  rest.unshift(path.basename(intended));
  while (true) {
    try {
      const realDir = await realpath(dir);
      assertRelInside(root, realDir, target);
      const planned = path.resolve(realDir, ...rest);
      assertRelInside(root, planned, target);
      return planned;
    } catch (error) {
      if ((error as Error).message?.startsWith("Path is outside")) throw error;
      const parent = path.dirname(dir);
      if (parent === dir) {
        assertRelInside(root, intended, target);
        return intended;
      }
      rest.unshift(path.basename(dir));
      dir = parent;
    }
  }
}

async function isLink(target: string) {
  try {
    return (await lstat(target)).isSymbolicLink();
  } catch {
    return false;
  }
}

/** Walk until an existing path, realpath it, refuse if it is outside cwd. */
async function existingRealDirInsideCwd(start: string, root: string, label: string) {
  const rest: string[] = [];
  let dir = start;
  while (true) {
    try {
      const real = await realpath(dir);
      assertRelInside(root, real, label);
      const info = await stat(real);
      if (!info.isDirectory()) {
        throw new Error(`Path is outside the working folder: ${label}`);
      }
      return { real, rest };
    } catch (error) {
      if ((error as Error).message?.startsWith("Path is outside")) throw error;
      const code = (error as NodeJS.ErrnoException).code;
      if (code && code !== "ENOENT") throw error;
      const parent = path.dirname(dir);
      if (parent === dir) {
        throw new Error(`Path is outside the working folder: ${label}`);
      }
      rest.unshift(path.basename(dir));
      dir = parent;
    }
  }
}

/** Write through the real parent directory. Never follow a dest link. mkdir only after that check. */
export async function writeFileInsideCwd(relativePath: string, contents: string, cwd: string) {
  const intended = lexicalInsideCwd(relativePath, cwd);
  const root = await realpathOrSelf(path.resolve(cwd));
  const parentLex = path.dirname(intended);
  const located = await existingRealDirInsideCwd(parentLex, root, relativePath);
  const destParent = located.rest.length
    ? path.join(located.real, ...located.rest)
    : located.real;
  assertRelInside(root, destParent, relativePath);
  if (located.rest.length) {
    await mkdir(destParent, { recursive: true });
  }
  const parentReal = await realpath(destParent);
  assertRelInside(root, parentReal, relativePath);
  const dest = path.join(parentReal, path.basename(intended));
  assertRelInside(root, dest, relativePath);
  const tmp = path.join(parentReal, `.aegis-tmp-${randomUUID()}`);
  try {
    await writeFile(tmp, contents, { encoding: "utf8", flag: "wx" });
    const parentNow = await realpath(destParent);
    if (path.resolve(parentNow) !== path.resolve(parentReal)) {
      throw new Error(`Path is outside the working folder: ${relativePath}`);
    }
    assertRelInside(root, parentNow, relativePath);
    if (await isLink(dest)) await unlink(dest);
    await rename(tmp, dest);
  } catch (error) {
    await unlink(tmp).catch(() => undefined);
    throw error;
  }
  if (await isLink(dest)) {
    await unlink(dest).catch(() => undefined);
    throw new Error(`Path is outside the working folder: ${relativePath}`);
  }
  const real = await realpath(dest);
  assertRelInside(root, real, relativePath);
  return real;
}

export async function assertWrittenInsideCwd(target: string, cwd: string) {
  const root = await realpathOrSelf(path.resolve(cwd));
  if (await isLink(target)) {
    await unlink(target).catch(() => undefined);
    throw new Error(`Path is outside the working folder: ${target}`);
  }
  try {
    const real = await realpath(target);
    assertRelInside(root, real, target);
  } catch {
    try {
      await unlink(target);
    } catch {
      // ignore
    }
    throw new Error(`Path is outside the working folder: ${target}`);
  }
}

src/gated.ts.body:
import { decideToolAction } from "./policy.ts";
import type {
  ConfirmFn,
  GateConfig,
  JevClient,
  JsonObject,
  ToolDecision,
  ToolRecord,
} from "./types.ts";
import { isGitRepo } from "./tools/fs.ts";

export type GatedRun = {
  output: string;
  record: ToolRecord;
  decision: ToolDecision;
};

const DISPLAY_LIMIT = 80_000;

function clipDisplay(text: string) {
  if (text.length <= DISPLAY_LIMIT) return text;
  return `${text.slice(0, DISPLAY_LIMIT)}\n  … [${text.length - DISPLAY_LIMIT} more bytes]`;
}

export function formatActionDiff(oldText: string, newText: string) {
  const oldLines = oldText.split("\n");
  const newLines = newText.split("\n");
  return ["  --- old", "  +++ new", ...oldLines.map((line) => `  - ${line}`), ...newLines.map((line) => `  + ${line}`)].join(
    "\n",
  );
}

export function formatConfirm(name: string, args: JsonObject, decision: ToolDecision) {
  const details =
    name === "edit"
      ? [
          `  path: ${String(args.path ?? "")}`,
          clipDisplay(formatActionDiff(String(args.old_string ?? ""), String(args.new_string ?? ""))),
        ].join("\n")
      : Object.entries(args)
          .map(([key, value]) => `  ${key}: ${clipDisplay(String(value ?? ""))}`)
          .join("\n");
  return [
    `Aegis: ${name}  ${decision.class}  data_loss=${decision.dataLoss.toFixed(2)}  via ${decision.source}`,
    details,
    "[y/N] ",
  ]
    .filter(Boolean)
    .join("\n");
}

function waitForAbort(signal?: AbortSignal) {
  return new Promise<void>((resolve) => {
    if (!signal) return;
    if (signal.aborted) {
      resolve();
      return;
    }
    signal.addEventListener("abort", () => resolve(), { once: true });
  });
}

function cancelled(decision: ToolDecision, name: string): GatedRun {
  const record: ToolRecord = {
    name,
    class: decision.class,
    dataLoss: decision.dataLoss,
    confidence: decision.confidence,
    action: "deny",
    approved: false,
    deniedReason: "cancelled",
    source: decision.source,
  };
  return {
    output: JSON.stringify({
      denied: true,
      reason: "cancelled",
      class: decision.class,
    }),
    record,
    decision,
  };
}

export async function runGatedTool(input: {
  name: string;
  args: JsonObject;
  cwd: string;
  jev: JevClient;
  config: GateConfig;
  confirm: ConfirmFn;
  execute: () => Promise<string>;
  abortSignal?: AbortSignal;
}): Promise<GatedRun> {
  const emptyDecision: ToolDecision = {
    class: "irreversible",
    dataLoss: 1,
    confidence: 0,
    probabilities: { class: { read_only: 0, reversible: 0, irreversible: 1 } },
    source: "fail_closed",
  };
  if (input.abortSignal?.aborted) {
    return cancelled(emptyDecision, input.name);
  }
  const decision = await input.jev.evaluateTool({
    name: input.name,
    args: input.args,
    cwd: input.cwd,
    git: isGitRepo(input.cwd),
  });
  if (input.abortSignal?.aborted) {
    return cancelled(decision, input.name);
  }
  const action = decideToolAction(decision, input.config);
  const record: ToolRecord = {
    name: input.name,
    class: decision.class,
    dataLoss: decision.dataLoss,
    confidence: decision.confidence,
    action,
    approved: false,
    source: decision.source,
  };

  if (action === "deny") {
    record.deniedReason = "jev fail-closed";
    return {
      output: JSON.stringify({
        denied: true,
        reason: "jev fail-closed: mutations blocked until live Jev returns a valid class",
        class: decision.class,
      }),
      record,
      decision,
    };
  }

  if (action === "confirm") {
    const prompt = formatConfirm(input.name, input.args, decision);
    const raced = await Promise.race([
      input.confirm(prompt).then((ok) => ({ kind: "answer" as const, ok })),
      waitForAbort(input.abortSignal).then(() => ({ kind: "abort" as const })),
    ]);
    if (raced.kind === "abort" || input.abortSignal?.aborted) {
      return cancelled(decision, input.name);
    }
    if (!raced.ok) {
      record.deniedReason = "user declined";
      return {
        output: JSON.stringify({
          denied: true,
          reason: "user declined",
          class: decision.class,
        }),
        record,
        decision,
      };
    }
  }

  if (input.abortSignal?.aborted) {
    return cancelled(decision, input.name);
  }

  record.approved = true;
  const output = await input.execute();
  return { output, record, decision };
}

