import { mkdir, readFile, appendFile } from "node:fs/promises";
import path from "node:path";
import { harnessRoot } from "./session.ts";

export function memoryPath(cwd: string) {
  return path.join(harnessRoot(cwd), "memory.md");
}

export async function loadMemory(cwd: string) {
  try {
    return (await readFile(memoryPath(cwd), "utf8")).trim();
  } catch {
    return "";
  }
}

export async function addMemory(cwd: string, note: string) {
  const file = memoryPath(cwd);
  await mkdir(path.dirname(file), { recursive: true });
  const line = `- ${new Date().toISOString().slice(0, 10)} ${note.trim()}\n`;
  await appendFile(file, line, "utf8");
  return line.trim();
}

src/model-pin.ts.body:
import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { currentCatalog, resolveModel } from "./catalog.ts";
import type { ChatProvider } from "./providers.ts";
import { harnessRoot } from "./session.ts";
import type { GateConfig } from "./types.ts";

export function modelFile(cwd: string) {
  return path.join(harnessRoot(cwd), "model");
}

export async function loadPinnedModel(cwd: string) {
  try {
    return (await readFile(modelFile(cwd), "utf8")).trim();
  } catch {
    return "";
  }
}

export async function setPinnedModel(cwd: string, id: string) {
  const resolved = resolveModel(id, currentCatalog());
  if (!resolved.ok) throw new Error(resolved.message);
  await mkdir(harnessRoot(cwd), { recursive: true });
  await writeFile(modelFile(cwd), `${resolved.id}\n`, "utf8");
  return resolved.id;
}

export async function clearPinnedModel(cwd: string) {
  try {
    await unlink(modelFile(cwd));
  } catch {
    // no pin
  }
}

export function defaultModelId(input: {
  pin?: string;
  override?: string;
  provider?: ChatProvider;
  config?: GateConfig;
}) {
  return input.override?.trim() || input.pin?.trim() || "";
}

src/planner.ts.body:
export type LocalPlan =
  | { tool: "read"; path: string }
  | { tool: "grep"; pattern: string; path: string }
  | { tool: "none" };

function cleanPath(raw: string) {
  return raw.trim().replace(/^["']|["']$/g, "") || ".";
}

export function planLocal(prompt: string): LocalPlan {
  const text = prompt.trim();
  const read = text.match(/^(?:read|open|cat|show)\s+(\S+)/i);
  if (read) return { tool: "read", path: cleanPath(read[1]) };

  const grep = text.match(/^(?:search|find|grep)\s+(?:for\s+)?(.+)$/i);
  if (grep) return { tool: "grep", pattern: grep[1].trim(), path: "." };

  if (/\b(list|ls|files|folder|directory|cwd)\b/i.test(text)) {
    return { tool: "read", path: "." };
  }
  return { tool: "none" };
}

