export const TURN_KINDS = ["lookup", "edit", "architecture"] as const;
export type TurnKind = (typeof TURN_KINDS)[number];

export const DIFFICULTY_LABELS = ["trivial", "minor", "moderate", "hard"] as const;
export type DifficultyLabel = (typeof DIFFICULTY_LABELS)[number];

export const TOOL_CLASSES = ["read_only", "reversible", "irreversible"] as const;
export type ToolClass = (typeof TOOL_CLASSES)[number];

export type PolicyAction = "auto" | "confirm" | "deny";

export type TurnState = {
  prompt: string;
  cwd: string;
  recent_tools: string[];
  open_files: string[];
};

export type JsonObject = { [key: string]: string | number | boolean | null };

export type ToolState = {
  name: string;
  args: JsonObject;
  cwd: string;
  git: boolean;
};

export type TurnDecision = {
  kind: TurnKind;
  difficulty: number;
  difficultyLabel: DifficultyLabel;
  needsRepoWide: number;
  confidence: number;
  probabilities: { kind: Record<TurnKind, number> };
  source: "jev" | "mock" | "fail_closed";
};

export type ToolDecision = {
  class: ToolClass;
  dataLoss: number;
  confidence: number;
  probabilities: { class: Record<ToolClass, number> };
  source: "jev" | "mock" | "fail_closed";
};

export type GateConfig = {
  jevModel: string;
  cheapModel: string;
  frontierModel: string;
  needsRepoWideThreshold: number;
  highConfidence: number;
  lowConfidence: number;
  dataLossThreshold: number;
  maxSteps: number;
  shellTimeoutMs: number;
};

export type JevClient = {
  evaluateTurn(state: TurnState): Promise<TurnDecision>;
  evaluateTool(state: ToolState): Promise<ToolDecision>;
};

export type ConfirmFn = (question: string) => Promise<boolean>;

export type JevHealth = "mock" | "live" | "down" | "blocked";

export type ToolRecord = {
  name: string;
  class: ToolClass;
  dataLoss: number;
  confidence: number;
  action: PolicyAction;
  approved: boolean;
  deniedReason?: string;
  source?: "jev" | "mock" | "fail_closed";
};

export type Receipt = {
  sessionId: string;
  prompt: string;
  model: string;
  routeReason: string;
  turn: TurnDecision;
  tools: ToolRecord[];
  ms: number;
  millicents: number;
  text: string;
};

